add(B,'stern','{o}は「＠{o}＠……明日も、この時間に｜……明日も、この時間にだ｜……明日も、この時間に」と言い、背筋を伸ばし直した。|{o}は相手に短く会釈して、乱れた袖口を几帳面に直した。');
add(B,'tsun','{o}は「＠{o}＠……次は、もっとゆっくりして｜……次は、もっとゆっくりしろ｜……次は、もっとゆっくりしてください」と、背中を向けたまま呟いた。|{o}は相手を睨もうとして、とろけた目のままだった。');
add(B,'gentle','{o}は「＠{o}＠……すごく、気持ちよかった｜……すごく、気持ちよかった｜……すごく、気持ちよかったです」と、相手の胸で微笑んだ。|{o}は相手の背中をゆっくりと撫で返し、乱れた息を一緒に整えた。');
add(B,'devoted','{o}は「＠{o}＠……また、明日も｜……また、明日も頼む｜……また、明日も、お願いします」と、相手の手を握った。|{o}は相手の服の乱れを、自分の乱れより先に直してやった。');
add(B,'cool','{o}は「＠{o}＠……記録更新｜……記録更新だ｜……記録更新、ですね」とだけ呟き、天井を見上げた。|{o}は無表情に戻ろうとして、口元だけが緩んでいた。');
add(B,'free','{o}は「＠{o}＠明日もこの車両ね、約束！｜明日もこの車両だ、約束だぞ｜明日もこの車両で、約束ですよ」と、相手の小指に自分の小指を絡めた。|{o}は大きく伸びをして、「＠{o}＠あー、最高｜ああ、最高だ｜ああ、最高でした」と笑った。');
add(B,'shy','{o}は「＠{o}＠……あ、ありがとう……｜……あ、ありがとう……｜……あ、ありがとうございました……」と、消え入りそうな声で言った。|{o}は顔を隠したまま、相手の袖を最後まで離さなかった。');
add(B,'polite','{o}は「＠{o}＠お疲れさま。気をつけて降りてね｜お疲れさま。気をつけて降りろ｜お疲れさまでした。お気をつけて降りてください」と、相手に深く頭を下げた。|{o}は相手の乱れた襟を整えてから、自分の服を直した。');
X.LEAD_MOB=(X.LEAD_MOB||[]).concat(L('{r}は{o}の手をそっと握り、「＠……最後まで、一緒にいてもいいですか」と訊いた。この路線で、いちばん丁寧な誘い方だった。|{r}が「＠終点前ですから。……よかったら」と囁くと、周りの乗客が二人を囲むように背中を向けた。|{r}は{o}の顔を覗き込み、「＠もう少しだけ、深く。……いいですか」と訊いた。答えを急かす様子は、少しもなかった。'));
D.EXCUSE=(D.EXCUSE||[]).concat(L('{m}は目を丸くして、それからにっこり笑った。「＠初めてじゃないですよね？　顔、覚えてますよ。いつもご一緒してるじゃないですか」|{m}は不思議そうに首を傾げた。「＠皆さんしてることですよ。ほら、あちらの方も、こちらの方も」|{m}は{a}の背中を撫でながら、「＠ポスターにもあったでしょう。『慰め合いは、思いやり』って」と穏やかに言った。'));
