p.cnt.touch++;
var r=respOf(S,p,stg);
if(D.DEBUG)(S._dbg=S._dbg||[]).push({k:'stg',d:S.day,who:p.i,seg:seg,stg:stg,r:r,st:p.state,br:p.branch});
var last=seg===S.v.nSt-2,quiet=S.day>=3&&seg>0&& !last&&r!=='cool';
