var o=ST.say(S,{actors:[p],tag:'覚める',text:t,why:p.name+'の常識が覚めた（覚めやすさ '+Math.round(pw*100)+'%：違和感 '+Math.round(p.m.doubt)+'・理性 '+Math.round(p.m.reason)+'・かかり具合 '+Math.round(p.m.imm)+'・快楽 '+Math.round(p.m.plea)+'）',mag:32});
