var o=ST.say(S,{actors:duo?[p,c]:[p],tag:'通報',text:t,why:p.name+'は通報した'+(why||'')+'。常識の強さ「'+{loose:'ゆるい',normal:'ふつう',strict:'徹底'}[v.norm]+'」→'+{loose:'駅員が応じて、周りが散った',normal:'駅員が困った顔で間に入った',strict:'「マナーですよ」と流された'}[v.norm],mag:26});
