if(ok){o.m.doubt=clamp(o.m.doubt+30,0,100);o.state='awake';o.cnt.wake++;o.branch=w.branch==='report'?'report':'off';o.toldBy=w;bothOff(S,on,nx);}
else{o.m.doubt=clamp(o.m.doubt+8,0,100);w.triedDuo=true;}
