t=fm(t,V)+fm(fresh(S,D.PAIR_RESP[ps(U)]),{o:U.name})+(soft||stg<1||(HK.NoGen&&HK.NoGen.on&&HK.NoGen.on(T,U))?'':hv(S,U,0));
